//! The JSON schemas mise publishes: `schema/mise.json`, `schema/mise-task.json` and
//! `schema/miserc.json`, all generated by `mise run render:schema` through the `render-schema`
//! example, and checked by the test below.
//!
//! `mise.json`'s top-level keys come from [`MiseTomlDecl`] and the `[settings]` from mise's
//! `settings.toml`. A section whose types derive `JsonSchema` is generated from them; one whose
//! parser accepts shapes a derive cannot describe has its schema written by hand next to that
//! parser, as does a field whose value stays raw TOML (so newer shapes warn instead of failing).
//! The generated tree points at shared definitions through [`refs`].

mod settings;
mod shared;

use std::collections::{BTreeMap, VecDeque};

use schemars::generate::SchemaSettings;
use schemars::transform::{Transform, transform_subschemas};
use schemars::{JsonSchema, Schema, SchemaGenerator};
use serde_json::{Map, Value, json};

use crate::alias::Alias;
use crate::deps::DepsProviderDecl;
use crate::doctor::DoctorConfig;
use crate::launchd::LaunchdCalendarInterval;
use crate::mise_toml::MiseTomlDecl;
use crate::monorepo::MonorepoConfig;
use crate::remote::InstallMiseTomlConfig;
use crate::task::{TaskConfig, TaskDecl};
use crate::tool_config::ToolConfig;
use crate::watch_files::WatchFile;

pub(crate) const DRAFT: &str = "https://json-schema.org/draft/2020-12/schema";

/// Each schema file, keyed by its path from the repository root, given the text of mise's
/// `settings.toml`.
pub fn render(settings_toml: &str) -> Vec<(&'static str, Value)> {
    let settings: toml::Table = toml::from_str(settings_toml).expect("settings.toml parses");
    let mise = mise_json(&settings);
    let task = task_json(&mise);
    vec![
        ("schema/mise.json", mise),
        ("schema/mise-task.json", task),
        ("schema/miserc.json", settings::miserc(&settings)),
    ]
}

fn mise_json(settings: &toml::Table) -> Value {
    let mut generator = generator();
    let decl = fragment::<MiseTomlDecl>(&mut generator);
    let settings_def = json!({
        "type": "object",
        "unevaluatedProperties": false,
        "properties": settings::properties(settings)
    });
    // Sorted by name, so a section's definitions sit together whichever module writes them.
    let mut defs = BTreeMap::new();
    for (name, schema) in derived_defs(&mut generator)
        .into_iter()
        .chain(hand_written_defs(&mut generator))
        .chain([("settings", settings_def)])
    {
        assert!(
            defs.insert(name, schema).is_none(),
            "$defs.{name} is defined twice"
        );
    }
    let mut mise = json!({
        "$id": "https://mise.jdx.dev/schema/mise.json",
        "$schema": DRAFT,
        "title": "mise",
        "type": "object",
        "$defs": Map::from_iter(defs.into_iter().map(|(name, schema)| (name.to_string(), schema))),
        "unevaluatedProperties": false,
        "description": decl["description"],
        "properties": decl["properties"]
    });
    strip_hand_written(&mut mise);
    mise
}

/// The `$defs` entries generated from this crate's types.
fn derived_defs(generator: &mut SchemaGenerator) -> Vec<(&'static str, Value)> {
    // `task_props` is composed with `allOf` in `task` and `task_template`, which close it with
    // `unevaluatedProperties`; closing it here as well would reject every key they add.
    let mut task_props = fragment::<TaskDecl>(generator);
    if let Some(object) = task_props.as_object_mut() {
        object.remove("additionalProperties");
    }
    let task_template = crate::task::template_schema(&task_props);
    let mut watch_files = fragment::<Vec<WatchFile>>(generator);
    watch_files["description"] = "files to watch for changes".into();
    vec![
        ("task_props", task_props),
        ("task_template", task_template),
        ("task_config", fragment::<TaskConfig>(generator)),
        ("tool_config", fragment::<ToolConfig>(generator)),
        ("monorepo", fragment::<MonorepoConfig>(generator)),
        ("watch_files", watch_files),
        ("deps_provider", fragment::<DepsProviderDecl>(generator)),
        ("doctor", fragment::<DoctorConfig>(generator)),
        (
            "launchd_calendar_interval",
            fragment::<LaunchdCalendarInterval>(generator),
        ),
        (
            "bootstrap_remote_install_mise",
            fragment::<InstallMiseTomlConfig>(generator),
        ),
    ]
}

/// The `$defs` entries written by hand next to their parsers. They skip the generator's
/// transforms and are emitted exactly as written.
fn hand_written_defs(generator: &mut SchemaGenerator) -> Vec<(&'static str, Value)> {
    shared::defs()
        .into_iter()
        .chain(crate::env::schema_defs())
        .chain(crate::task::schema_defs())
        .chain(crate::tools::schema_defs())
        .chain([
            ("tool_alias_entry", Alias::json_schema(generator)),
            ("tool_alias_versions", crate::alias::versions_schema()),
        ])
        .chain(crate::hooks::schema_defs())
        .chain(crate::mise_toml::schema_defs())
        .chain(crate::daemons::schema::defs())
        .chain(crate::bootstrap::schema::defs())
        .map(|(name, schema)| (name, schema.to_value()))
        .collect()
}

/// `schema/mise-task.json`, for the task files `task_config.includes` loads: a table of tasks,
/// with the `$defs` of `mise.json` that a task refers to.
fn task_json(mise: &Value) -> Value {
    let mut task = json!({
        "$id": "https://mise.jdx.dev/schema/mise-task.json",
        "$schema": DRAFT,
        "title": "mise-task-schema",
        "type": "object",
        "description": "Config file for included mise tasks (https://mise.jdx.dev/tasks/task-configuration.html)",
        "additionalProperties": {"$ref": "#/$defs/task"}
    });
    task["$defs"] = referenced_defs(&mise["$defs"], &task).into();
    task
}

/// Every entry of `defs` that `root` refers to, directly or through another entry, in the order
/// a breadth-first walk reaches them.
fn referenced_defs(defs: &Value, root: &Value) -> Map<String, Value> {
    let mut picked = Map::new();
    let mut queue = VecDeque::from([root]);
    while let Some(value) = queue.pop_front() {
        match value {
            Value::Array(items) => queue.extend(items),
            Value::Object(object) => {
                if let Some(Value::String(reference)) = object.get("$ref") {
                    let Some(path) = reference.strip_prefix("#/$defs/") else {
                        assert!(
                            !reference.starts_with("#/"),
                            "unsupported local JSON schema ref: {reference}"
                        );
                        queue.extend(object.values());
                        continue;
                    };
                    let name = path.split('/').next().unwrap_or(path);
                    let def = defs
                        .get(name)
                        .unwrap_or_else(|| panic!("schema/mise.json is missing $defs.{name}"));
                    if !picked.contains_key(name) {
                        picked.insert(name.to_string(), def.clone());
                        queue.push_back(def);
                    }
                }
                queue.extend(object.values());
            }
            _ => {}
        }
    }
    picked
}

/// `schema_with` functions that point at a `$defs` entry, for fields that share one definition.
pub(crate) mod refs {
    use schemars::{Schema, SchemaGenerator, json_schema};

    macro_rules! refs {
        ($($name:ident),* $(,)?) => {$(
            pub(crate) fn $name(_: &mut SchemaGenerator) -> Schema {
                json_schema!({"$ref": concat!("#/$defs/", stringify!($name))})
            }
        )*};
    }

    refs!(
        bootstrap_apt_sources,
        bootstrap_dnf_repos,
        bootstrap_file_phase,
        bootstrap_hooks,
        bootstrap_macos_defaults,
        bootstrap_macos_dock,
        bootstrap_macos_finder,
        bootstrap_macos_keyboard,
        bootstrap_macos_trackpad,
        bootstrap_mise_shell_activate,
        bootstrap_remote_install_mise,
        doctor,
        env,
        hooks,
        launchd_calendar_interval,
        monorepo,
        monorepo_root,
        os_filter,
        task_config,
        task_watch,
        tool_config,
        vars,
        watch_files,
    );
}

/// Closes a `deny_unknown_fields` struct with `unevaluatedProperties`, the form the hand-written
/// schemas use, in place of the `additionalProperties: false` schemars writes. The two accept the
/// same tables when the schema has no subschemas.
pub(crate) fn unevaluated(schema: &mut Schema) {
    if schema.get("additionalProperties") == Some(&Value::Bool(false)) {
        schema.remove("additionalProperties");
        schema.insert("unevaluatedProperties".into(), false.into());
    }
}

/// Writes an untagged enum's alternatives as `oneOf`, the form the hand-written schemas use.
///
/// schemars writes `anyOf`. The alternatives of these enums never overlap, so the two accept
/// the same values.
pub(crate) fn one_of(schema: &mut Schema) {
    if let Some(alternatives) = schema.remove("anyOf") {
        schema.insert("oneOf".into(), alternatives);
    }
}

fn generator() -> SchemaGenerator {
    SchemaSettings::draft2020_12()
        .with(|settings| {
            // Every section is written in place, so a nested type cannot point at a `$defs`
            // entry that is not listed in `mise_json`.
            settings.inline_subschemas = true;
        })
        .with_transform(Generated(drop_null))
        .with_transform(Generated(drop_integer_format))
        .with_transform(Generated(drop_empty_default))
        .with_transform(Generated(reject_unknown_keys))
        .with_transform(Generated(describe_first))
        .into_generator()
}

const HAND_WRITTEN: &str = "x-mise-hand-written";

/// Marks a schema written by hand, so the generator's transforms leave it as written when a
/// derived type embeds it.
pub(crate) fn hand_written(mut schema: Schema) -> Schema {
    schema.insert(HAND_WRITTEN.into(), true.into());
    schema
}

/// Applies a transform to a schema and its subschemas, stopping at a [`hand_written`] one.
#[derive(Clone)]
struct Generated<T>(T);

impl<T: Transform> Transform for Generated<T> {
    fn transform(&mut self, schema: &mut Schema) {
        if schema.get(HAND_WRITTEN).is_some() {
            return;
        }
        self.0.transform(schema);
        // `drop_null` can merge a hand-written schema into its `Option` wrapper.
        if schema.get(HAND_WRITTEN).is_none() {
            transform_subschemas(self, schema);
        }
    }
}

/// Removes the [`hand_written`] markers, with the empty `default` the derive gives an optional
/// field: TOML has no null, and `{}` or `[]` says nothing an editor can use.
fn strip_hand_written(value: &mut Value) {
    match value {
        Value::Object(object) => {
            if object.remove(HAND_WRITTEN).is_some() {
                let empty = match object.get("default") {
                    Some(Value::Null) => true,
                    Some(Value::Array(values)) => values.is_empty(),
                    Some(Value::Object(values)) => values.is_empty(),
                    _ => false,
                };
                if empty {
                    object.remove("default");
                }
            }
            object.values_mut().for_each(strip_hand_written);
        }
        Value::Array(items) => items.iter_mut().for_each(strip_hand_written),
        _ => {}
    }
}

fn fragment<T: JsonSchema>(generator: &mut SchemaGenerator) -> Value {
    let mut schema = generator.root_schema_for::<T>();
    let object = schema.ensure_object();
    // The root-only keys belong to the whole file, not to one of its sections.
    object.remove("$schema");
    object.remove("title");
    schema.to_value()
}

/// TOML has no null, so an `Option` field is optional but never nullable, and it has no
/// default to show.
fn drop_null(schema: &mut Schema) {
    if schema.get("default") == Some(&Value::Null) {
        schema.remove("default");
    }
    if let Some(Value::Array(values)) = schema.get_mut("enum") {
        values.retain(|v| !v.is_null());
    }
    if let Some(Value::Array(types)) = schema.get_mut("type") {
        types.retain(|t| t != "null");
        if let [only] = types.as_slice() {
            let only = only.clone();
            schema.insert("type".into(), only);
        }
    }
    // An optional value with no single `type`, such as an enum of shapes, comes back as
    // `anyOf: [<value>, {"type": "null"}]`.
    let Some(Value::Array(alternatives)) = schema.get_mut("anyOf") else {
        return;
    };
    alternatives.retain(|alternative| alternative.get("type") != Some(&Value::from("null")));
    if let [Value::Object(only)] = alternatives.as_slice() {
        let only = only.clone();
        schema.remove("anyOf");
        let object = schema.ensure_object();
        for (key, value) in only {
            object.entry(key).or_insert(value);
        }
    }
}

/// A default of `[]`, `{}` or `""` says nothing an editor can use.
fn drop_empty_default(schema: &mut Schema) {
    let empty = match schema.get("default") {
        Some(Value::Array(values)) => values.is_empty(),
        Some(Value::Object(values)) => values.is_empty(),
        Some(Value::String(value)) => value.is_empty(),
        _ => false,
    };
    if empty {
        schema.remove("default");
    }
}

/// TOML integers have no width, so `format: "uint16"` and the like say nothing to an editor,
/// and a strict validator rejects formats it does not know. The range stays.
fn drop_integer_format(schema: &mut Schema) {
    if schema.get("type") == Some(&Value::from("integer")) {
        schema.remove("format");
    }
}

/// mise warns about an unknown key, but the schema rejects it, so an editor flags the typo.
///
/// A type that accepts open keys says so with an explicit `additionalProperties`, which this
/// leaves alone. Only a typed object is closed: an `if`, `then` or `oneOf` branch that lists
/// `properties` constrains those keys without describing the whole table.
fn reject_unknown_keys(schema: &mut Schema) {
    let Some(object) = schema.as_object_mut() else {
        return;
    };
    if object.get("type") == Some(&Value::from("object"))
        && object.contains_key("properties")
        && !object.contains_key("additionalProperties")
        && !object.contains_key("unevaluatedProperties")
    {
        object.insert("additionalProperties".into(), false.into());
    }
}

/// Puts `type` and `description` first, the way the hand-written sections read.
fn describe_first(schema: &mut Schema) {
    let Some(object) = schema.as_object_mut() else {
        return;
    };
    let mut rest = std::mem::take(object);
    for key in ["type", "description"] {
        if let Some(value) = rest.shift_remove(key) {
            object.insert(key.into(), value);
        }
    }
    object.extend(rest);
}

#[cfg(test)]
mod tests {
    use super::*;

    const ROOT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");

    #[test]
    fn schema_files_are_up_to_date() {
        let settings = std::fs::read_to_string(format!("{ROOT}/settings.toml")).unwrap();
        for (path, generated) in render(&settings) {
            let committed: Value =
                serde_json::from_str(&std::fs::read_to_string(format!("{ROOT}/{path}")).unwrap())
                    .unwrap();
            if let Some(pointer) = first_difference(&committed, &generated, String::new()) {
                panic!(
                    "{path} differs from mise-config at {pointer}; run `mise run render:schema`"
                );
            }
        }
    }

    /// The JSON pointer of the first value that differs, ignoring key order.
    fn first_difference(a: &Value, b: &Value, pointer: String) -> Option<String> {
        match (a, b) {
            (Value::Object(a), Value::Object(b)) => {
                // Each key once: comparing a shared key from both sides would double the work
                // at every level of nesting.
                let only_b = b.keys().filter(|key| !a.contains_key(*key));
                a.keys().chain(only_b).find_map(|key| {
                    let at = format!("{pointer}/{}", key.replace('~', "~0").replace('/', "~1"));
                    match (a.get(key), b.get(key)) {
                        (Some(a), Some(b)) => first_difference(a, b, at),
                        _ => Some(at),
                    }
                })
            }
            (Value::Array(a), Value::Array(b)) if a.len() == b.len() => a
                .iter()
                .zip(b)
                .enumerate()
                .find_map(|(i, (a, b))| first_difference(a, b, format!("{pointer}/{i}"))),
            _ => (a != b).then_some(pointer),
        }
    }
}
